.text-link:hover {color: #2d3127;}
.forgot-link {font-size: 12px; color: #72776a;}
.password-field {margin-bottom: 20px;}
.remember-checkbox {color: #65685f; font-size: 13px;}
.remember-checkbox .g-checkbox__content {font-size: 13px;}
.submit-button {margin-top: 27px; font-weight: 600;}
.submit-button .g-button__text {display: flex; align-items: center; justify-content: center; gap: 12px; font-size: 14px;}
.submit-notice {margin-top: 18px;}
.access-note {margin-top: 30px; padding-top: 25px; border-top: 1px solid #eeefea; text-align: center; font-size: 12px; line-height: 1.7; color: #75786f;}
.access-note > span {color: #51564a; font-weight: 500;}
.access-note p {margin: 3px -10px 0;}
.secure-note {margin-top: 34px; display: flex; align-items: center; justify-content: center; gap: 7px; color: #9b9e95; font-size: 10px;}
.form-footer {display: flex; justify-content: space-between; gap: 16px; color: #96998f; font-size: 10px;}
.powered-by {display: flex; gap: 5px;}.powered-by a {display: flex; align-items: center; gap: 3px; color: #676d5e;}.powered-by a:hover {text-decoration: underline;}
.info-dialog {padding: 32px; max-width: 450px;}.info-dialog h2 {font-size: 24px; line-height: 1.3; margin-top: 0;}.info-dialog p {color: #6a6d64; font-size: 14px; line-height: 1.7; margin-bottom: 24px;}
@media (min-width: 1500px) {.brand-panel {padding-left: 64px; padding-right: 64px;}.brand-story {max-width: 550px;}.orbit-art {height: 370px;}}
@media (max-width: 1050px) {.brand-panel {padding-left: 32px; padding-right: 32px;}.form-panel {padding-left: 36px; padding-right: 36px;}.brand-footer span:last-child {display: none;}.eyebrow {font-size: 9px; letter-spacing: 1.2px;}.orbit-art {height: 300px;}.brand-description {font-size: 13px;}.brand-caption {font-size: 10px;}.gravity-cube {width: 110px; height: 110px;}}
@media (max-width: 760px) {.login-page {display: flex; flex-direction: column;}.brand-panel {padding: 23px 26px; border-right: 0; border-bottom: 1px solid #eeeee8;}.brand {font-size: 25px; line-height: 32px;}.brand-icon {width: 31px; height: 31px; border-radius: 9px;}.brand-icon svg {width: 23px;}.brand-story, .brand-footer {display: none;}.form-panel {flex: 1; min-height: calc(100svh - 79px); padding: 24px 26px;}.form-header {position: absolute; top: 22px; right: 18px;}.form-content {padding: 43px 0 48px;}.form-heading h2 {font-size: 29px;}.form-footer {font-size: 10px;}.welcome-icon {margin-bottom: 23px;}.info-dialog {max-width: calc(100vw - 32px); padding: 25px;}}
@media (prefers-reduced-motion: no-preference) {.gravity-cube {animation: float 7s ease-in-out infinite;}@keyframes float {0%, 100% {translate: 0 0;}50% {translate: 0 -9px;}}}
EOF
npm run build"

