button:focus-visible, a:focus-visible {outline: 2px solid #8c7424; outline-offset: 4px; border-radius: 4px;}
.login-page {min-height: 100svh; display: grid; grid-template-columns: 48% 52%;}
.brand-panel {background: #f5f5ef; padding: 40px 48px 27px; display: flex; flex-direction: column; position: relative; overflow: hidden; border-right: 1px solid #eeeee8;}
.brand {display: inline-flex; align-items: center; gap: 10px; align-self: flex-start; font-size: 30px; font-weight: 750; letter-spacing: -1.4px; line-height: 40px;}
.brand-icon {width: 36px; height: 36px; background: #ffdb4d; border-radius: 10px; display: grid; place-items: center;}
.brand-icon svg {width: 26px; height: 26px;}
.brand-period {color: #a28b39;}
.brand-story {width: 100%; max-width: 520px; margin: auto; padding-top: 68px; padding-bottom: 55px;}
.eyebrow {font-size: 10px; letter-spacing: 1.65px; font-weight: 600; display: flex; align-items: center; gap: 9px; color: #696b61;}
.status-dot {height: 6px; width: 6px; border-radius: 50%; background: #7c8d65; box-shadow: 0 0 0 4px #e8ebdf;}
h1 {font-size: clamp(35px, 3.5vw, 53px); font-weight: 550; letter-spacing: -1.9px; line-height: 1.17; margin: 24px 0 19px;}
.yellow-period {color: #c8a72c;}
.brand-description {font-size: 15px; line-height: 1.7; color: #7a7b73; margin: 0;}
.orbit-art {height: 335px; position: relative; margin: 8px -25px 9px;}
.orbits {width: 100%; height: 100%; stroke: #dadcd1; stroke-width: 1; overflow: visible;}
.orbit-point {fill: #a6ad95; stroke: #f5f5ef; stroke-width: 3;}
.yellow-point {fill: #e9c948; stroke-width: 0;}
.gravity-cube {position: absolute; left: 50%; top: 51%; width: 126px; height: 126px; transform: translate(-50%, -50%) rotate(-13deg); border-radius: 30px; display: grid; place-items: center; color: #383625; background: linear-gradient(145deg, #ffe582 0%, #ffda52 45%, #f3ca38 100%); box-shadow: inset 0 2px 2px #fff2b7, inset -3px -5px 3px #d8af2d55, 7px 12px 0 -3px #d6b33b, 12px 28px 32px -12px #74672245;}
.gravity-cube svg {width: 77px; height: 77px; transform: rotate(3deg);}
.floating-tile {position: absolute; width: 59px; height: 59px; border-radius: 16px; background: #fdfdf9; border: 1px solid #fff; box-shadow: 0 8px 18px #484d3510, 0 2px 3px #484d3509; display: grid; place-items: center; color: #7c8567;}
.tile-small {left: 14%; top: 25%; transform: rotate(-14deg);}
.tile-small svg {width: 29px; fill: #90977f;}
.tile-check {right: 13%; bottom: 22%; transform: rotate(13deg);}
.art-spark {position: absolute; font-size: 21px; font-weight: 300; color: #a8ae97;}
.spark-one {left: 27%; bottom: 19%;}.spark-two {right: 20%; top: 21%; font-size: 17px;}
.brand-caption {display: flex; gap: 12px; align-items: center; color: #797c6e; font-size: 12px; letter-spacing: .05px;}
.caption-line {width: 25px; height: 1px; background: #aeb49d;}
.brand-footer {display: flex; justify-content: space-between; gap: 16px; font-size: 10px; color: #94968b;}
.form-panel {display: flex; flex-direction: column; padding: 39px 48px 27px; background: #fff;}
.form-header {display: flex; justify-content: flex-end; height: 40px; align-items: center;}
.form-header .g-button {font-size: 12px; color: #73756f;}
.form-content {width: 100%; max-width: 372px; margin: auto; padding: 60px 0 70px;}
.welcome-icon {height: 46px; width: 46px; border: 1px solid #e7e7e2; border-radius: 13px; display: grid; place-items: center; margin-bottom: 25px; box-shadow: 0 2px 3px #00000003; color: #55594e;}
.form-heading h2 {margin: 0 0 11px; font-size: 31px; font-weight: 550; line-height: 1.2; letter-spacing: -1px;}
.form-heading p {margin: 0; font-size: 14px; color: #858780; line-height: 1.5;}
form {margin-top: 35px;}
.form-field {margin-bottom: 23px;}
.form-field label {display: inline-block; font-size: 13px; font-weight: 500; margin-bottom: 9px;}
.form-field .g-text-input {--g-text-input-border-color: #dedfd9; --g-text-input-border-color-hover: #b9bcb0; --g-text-input-border-color-active: #ad9235; --g-text-input-background-color: #fff;}
.form-field .g-text-input__control {font-size: 14px;}
.form-field .g-text-input__control::placeholder {color: #a0a29b;}
.field-label-row {display: flex; align-items: baseline; justify-content: space-between;}
.text-link {font-family: inherit; font-size: inherit; padding: 0; border: 0; background: none; cursor: pointer; color: #82847c; transition: color .15s;}
.text-link:hover {color: #2d3127;}
.forgot-link {font-size: 12px; color: #72776a;}
.password-field {margin-bottom: 20px;}
.remember-checkbox {color: #65685f; font-size: 13px;}
.remember-checkbox .g-checkbox__content {font-size: 13px;}
.submit-button {margin-top: 27px; font-weight: 600;}
.submit-button .g-button__text {display: flex; align-items: center; justify-content: center; gap: 12px; font-size: 14px;}
.submit-notice {margin-top: 18px;}
.access-note {margin-top: 30px; padding-top: 25px; border-top: 1px solid #eeefea; text-align: center; font-size: 12px; line-height: 1.7; color: #75786f;}
.access-note > span {color: #51564a; font-weight: 500;}
.access-note p {margin: 3px -10px 0;}
.secure-note {margin-top: 34px; display: flex; align-items: center; justify-content: center; gap: 7px; color: #9b9e95; font-size: 10px;}
.form-footer {display: flex; justify-content: space-between; gap: 16px; color: #96998f; font-size: 10px;}
.powered-by {display: flex; gap: 5px;}.powered-by a {display: flex; align-items: center; gap: 3px; color: #676d5e;}.powered-by a:hover {text-decoration: underline;}
.info-dialog {padding: 32px; max-width: 450px;}.info-dialog h2 {font-size: 24px; line-height: 1.3; margin-top: 0;}.info-dialog p {color: #6a6d64; font-size: 14px; line-height: 1.7; margin-bottom: 24px;}
@media (min-width: 1500px) {.brand-panel {padding-left: 64px; padding-right: 64px;}.brand-story {max-width: 550px;}.orbit-art {height: 370px;}}
@media (max-width: 1050px) {.brand-panel {padding-left: 32px; padding-right: 32px;}.form-panel {padding-left: 36px; padding-right: 36px;}.brand-footer span:last-child {display: none;}.eyebrow {font-size: 9px; letter-spacing: 1.2px;}.orbit-art {height: 300px;}.brand-description {font-size: 13px;}.brand-caption {font-size: 10px;}.gravity-cube {width: 110px; height: 110px;}}
@media (max-width: 760px) {.login-page {display: flex; flex-direction: column;}.brand-panel {padding: 23px 26px; border-right: 0; border-bottom: 1px solid #eeeee8;}.brand {font-size: 25px; line-height: 32px;}.brand-icon {width: 31px; height: 31px; border-radius: 9px;}.brand-icon svg {width: 23px;}.brand-story, .brand-footer {display: none;}.form-panel {flex: 1; min-height: calc(100svh - 79px); padding: 24px 26px;}.form-header {position: absolute; top: 22px; right: 18px;}.form-content {padding: 43px 0 48px;}.form-heading h2 {font-size: 29px;}.form-footer {font-size: 10px;}.welcome-icon {margin-bottom: 23px;}.info-dialog {max-width: calc(100vw - 32px); padding: 25px;}}
@media (prefers-reduced-motion: no-preference) {.gravity-cube {animation: float 7s ease-in-out infinite;}@keyframes float {0%, 100% {translate: 0 0;}50% {translate: 0 -9px;}}}
EOF
npm run build"

